mapper.select:
select
    wc.id,wc.spec_id,wc.box_no,wc.packing_status,wc.weighting_status,wc.packing_user_id,wc.packing_user_name,wc.error_msg,wc.packing_task_id
from wms_carton wc where wc.is_deleted = FALSE

    ${params.permissionSql}


    and wc.packing_task_id = #{params.taskId}

order by wc.box_no
